const payload = $json.body ?? $json;
const alert = Array.isArray(payload.alerts) ? payload.alerts[0] : {};
const traceId = payload.trace_id ?? alert?.labels?.trace_id ?? alert?.annotations?.trace_id;
if (typeof traceId !== 'string' || !/^[0-9a-f]{32}$/i.test(traceId)) {
  throw new Error('SigNoz payload must contain a 32-character trace_id');
}
return [{ json: { trace_id: traceId.toLowerCase(), alert_name: alert?.labels?.alertname ?? payload.alert_name ?? 'P95 latency > 2s', status: payload.status ?? 'firing', received_at: new Date().toISOString() } }];

const raw = $json.stdout?.trim();
if (!raw) throw new Error('Codex analysis returned no output');
const analysis = JSON.parse(raw.split('\n').at(-1));
if (!analysis.safe_to_remediate) throw new Error('Codex did not authorize the bounded remediation');
return [{ json: analysis }];

const raw = $json.stdout?.trim();
if (!raw) throw new Error('Codex remediation returned no output');
const result = JSON.parse(raw.split('\n').at(-1));
if (!result.executed || !result.verified || result.index_name !== 'searchField_1') {
  throw new Error('Remediation verification failed');
}
return [{ json: result }];

if ($json.index_present !== true || Number($json.latency_ms) >= 2000) {
  throw new Error(`Closed-loop verification failed: index=${$json.index_present}, latency_ms=${$json.latency_ms}`);
}
return items;
